such that the diagrams
$$
\vcenter{
\begin{array}{cc}X \underset{1}{\searrow}\underset{\eta \otimes 1}{\longrightarrow} & X \otimes Y \otimes X \overset{1 \otimes \epsilon}{\downarrow} \\  & X\end{array}
}
