\vcenter{
\begin{array}{cc}Y \underset{1}{\searrow}\underset{1 \otimes \eta}{\longrightarrow} & Y \otimes X \otimes Y \overset{\epsilon \otimes 1}{\downarrow} \\  & Y\end{array}
