\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0ASB}{\texttt{Stacks tag 0ASB}}


Let $A$ be a ring. Let $M$ be a flat $A$-module. Let $x \in M$.
The content ideal of $x$, if it exists, is finitely generated.

\href{https://stacks.math.columbia.edu/tag/0ASD}{\texttt{Stacks tag 0ASD}}


Let $A$ be a ring. Let $M$ be a flat Mittag-Leffler module.
Then every element of $M$ has a content ideal.

\href{https://stacks.math.columbia.edu/tag/053E}{\texttt{Stacks tag 053E}}


\begin{reference}
\cite[Theorem 3]{Nagata-Finitely}
\end{reference}
